        // first hub
        .WriteTo.Sink(new SignalRTelemetrySink(
            () => services.GetRequiredService<IHubContext<SignalRInternalTelemetryHub>>()))
        // second hub
        .WriteTo.Sink(new SignalRTelemetrySink(
            () => services.GetRequiredService<IHubContext<SignalRSecondaryTelemetryHub>>()));
});
```

