                    Log.Warning("No active connection found for DeviceID: {DeviceID}.", deviceGUID);

                }

            }

            catch (Exception ex)

            {

                Log.Error(ex, "Failed to send message to client with DeviceID {DeviceID}.", message.SendToGuid);

            }



            return false;

        }

