     * Start the HubConnection and set up handlers.
     */
    fun startService() {
        scope.launch {
            val fullUrl = buildUrl()
            log("Initializing SignalR connection to $fullUrl")
            hubConnection = HubConnectionBuilder.create(fullUrl)
                .withAutomaticReconnect()
                .build()

            setupHandlers()

            try {
                hubConnection.start().blockingAwait()
                log("SignalR connection started successfully for $hubPath")
            } catch (e: Exception) {
                log("Error starting SignalR connection for $hubPath: ${'$'}{e.message}")
                retryConnection()
            }
        }
    }

    /**
     * Stop the HubConnection if connected.
     */
    fun stopService() {
        scope.launch {
            try {
                if (this@BaseSignalRService::hubConnection.isInitialized &&
                    hubConnection.connectionState == HubConnectionState.CONNECTED) {
                    hubConnection.stop().blockingAwait()
                    log("SignalR connection stopped for $hubPath")
                }
            } catch (e: Exception) {
                log("Error stopping SignalR for $hubPath: ${'$'}{e.message}")
            }
        }
    }

